'use client';

import type { Variants } from 'motion/react';
import { motion, useAnimation } from 'motion/react';
import type { HTMLAttributes } from 'react';
import { forwardRef } from 'react';
import { useIconAnimation } from '@/lib/use-icon-animation';
import { cn } from '@/lib/utils';

export interface Mic01IconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}

interface Mic01IconProps extends HTMLAttributes<HTMLDivElement> {
  size?: number;
}

// while you hover, it's live — the grille bars pulse like an input meter
// and drawn sound arcs broadcast off both sides. The built-in grille (one
// path, two lockstep bars) hides during hover and hands off to two
// independently clocked bars, so the meter doesn't blink as one flat unit.
const grilleBaseVariants: Variants = {
  normal: { opacity: 1, transition: { duration: 0.3, delay: 0.1 } },
  animate: { opacity: 0, transition: { duration: 0.15 } },
};

// pathLength retract from the mic-body edge, like a VU bar
const grilleBarVariants: Variants = {
  normal: { pathLength: 1, opacity: 0, transition: { duration: 0.15 } },
  animate: (i: number) => ({
    opacity: 1,
    pathLength: [1, 0.3, 1],
    transition: {
      duration: 1 + i * 0.2,
      ease: 'easeInOut',
      repeat: Infinity,
      delay: i * 0.25,
    },
  }),
};

// custom: [direction, delay] — arcs drift outward as they fade
const waveVariants: Variants = {
  normal: { opacity: 0, transition: { duration: 0.15 } },
  animate: (c: [number, number]) => ({
    opacity: [0, 1, 0],
    translateX: [0, c[0] * 1.6],
    transition: {
      duration: 1.2,
      ease: 'easeOut',
      repeat: Infinity,
      delay: c[1],
    },
  }),
};
const generatedGeometryVariants: Variants = {
  normal: { opacity: 0, transition: { duration: 0.08 } },
  animate: { opacity: 1, transition: { duration: 0.08 } },
};


const Mic01Icon = forwardRef<Mic01IconHandle, Mic01IconProps>(
  ({ onMouseEnter, onMouseLeave, className, size = 28, ...props }, ref) => {
    const controls = useAnimation();
    const { handleMouseEnter, handleMouseLeave } = useIconAnimation({
      controls,
      loops: true,
      onMouseEnter,
      onMouseLeave,
      ref,
    });

    return (
      <div
        className={cn(className)}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
        {...props}
      >
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width={size}
          height={size}
          viewBox="0 0 24 24"
          fill="none"
          overflow="visible"
        >
          <path
            d="M17 7V11C17 13.7614 14.7614 16 12 16C9.23858 16 7 13.7614 7 11V7C7 4.23858 9.23858 2 12 2C14.7614 2 17 4.23858 17 7Z"
            stroke="currentColor"
            strokeWidth="1.5"
          />
          <motion.path
            d="M17 7H14M17 11H14"
            stroke="currentColor"
            strokeLinecap="round"
            strokeWidth="1.5"
            variants={grilleBaseVariants}
            animate={controls}
            initial="normal"
          />
          <path
            d="M20 11C20 15.4183 16.4183 19 12 19M12 19C7.58172 19 4 15.4183 4 11M12 19V22M12 22H15M12 22H9"
            stroke="currentColor"
            strokeLinecap="round"
            strokeWidth="1.5"
          />
          <motion.g
            variants={generatedGeometryVariants}
            animate={controls}
            initial="normal"
          >
          <motion.path
            d="M17 7H14"
            stroke="currentColor"
            strokeLinecap="round"
            strokeWidth="1.5"
            variants={grilleBarVariants}
            custom={0}
            animate={controls}
            initial="normal"
          />
          <motion.path
            d="M17 11H14"
            stroke="currentColor"
            strokeLinecap="round"
            strokeWidth="1.5"
            variants={grilleBarVariants}
            custom={1}
            animate={controls}
            initial="normal"
          />
          <motion.path
            d="M4.8 3.2C3.9 4.4 3.4 5.9 3.4 7.5"
            stroke="currentColor"
            strokeLinecap="round"
            strokeWidth="1.5"
            variants={waveVariants}
            custom={[-1, 0]}
            animate={controls}
            initial="normal"
          />
          <motion.path
            d="M19.2 3.2C20.1 4.4 20.6 5.9 20.6 7.5"
            stroke="currentColor"
            strokeLinecap="round"
            strokeWidth="1.5"
            variants={waveVariants}
            custom={[1, 0]}
            animate={controls}
            initial="normal"
          />
          <motion.path
            d="M2.6 1.4C1.5 2.9 0.9 4.9 0.9 7"
            stroke="currentColor"
            strokeLinecap="round"
            strokeWidth="1.5"
            variants={waveVariants}
            custom={[-1, 0.35]}
            animate={controls}
            initial="normal"
          />
          <motion.path
            d="M21.4 1.4C22.5 2.9 23.1 4.9 23.1 7"
            stroke="currentColor"
            strokeLinecap="round"
            strokeWidth="1.5"
            variants={waveVariants}
            custom={[1, 0.35]}
            animate={controls}
            initial="normal"
          />
          </motion.g>
        </svg>
      </div>
    );
  }
);

Mic01Icon.displayName = 'Mic01Icon';

export { Mic01Icon };

'use client';

import type { LegacyAnimationControls } from 'motion/react';
import { useReducedMotion } from 'motion/react';
import type {
  ForwardedRef,
  MouseEventHandler,
} from 'react';
import { useCallback, useImperativeHandle, useRef } from 'react';

export interface AnimatedIconHandle {
  startAnimation: () => void;
  stopAnimation: () => void;
}

interface UseIconAnimationOptions {
  controls: LegacyAnimationControls;
  loops?: boolean;
  onMouseEnter?: MouseEventHandler<HTMLDivElement>;
  onMouseLeave?: MouseEventHandler<HTMLDivElement>;
  ref: ForwardedRef<AnimatedIconHandle>;
}

export function useIconAnimation({
  controls,
  loops = false,
  onMouseEnter,
  onMouseLeave,
  ref,
}: UseIconAnimationOptions) {
  const shouldReduceMotion = useReducedMotion();
  const isControlledRef = useRef(false);
  const isPlayingRef = useRef(false);
  const runRef = useRef(0);

  const startAnimation = useCallback(() => {
    if (shouldReduceMotion || isPlayingRef.current) return;

    isPlayingRef.current = true;
    const run = ++runRef.current;
    controls.set('normal');
    void controls.start('animate').then(() => {
      if (runRef.current === run) isPlayingRef.current = false;
    });
  }, [controls, shouldReduceMotion]);

  const stopAnimation = useCallback(() => {
    if (!loops) return;

    runRef.current++;
    isPlayingRef.current = false;
    void controls.start('normal');
  }, [controls, loops]);

  useImperativeHandle(
    ref,
    () => {
      isControlledRef.current = true;
      return { startAnimation, stopAnimation };
    },
    [startAnimation, stopAnimation]
  );

  const handleMouseEnter = useCallback<MouseEventHandler<HTMLDivElement>>(
    (event) => {
      onMouseEnter?.(event);
      if (!isControlledRef.current) startAnimation();
    },
    [onMouseEnter, startAnimation]
  );

  const handleMouseLeave = useCallback<MouseEventHandler<HTMLDivElement>>(
    (event) => {
      onMouseLeave?.(event);
      if (!isControlledRef.current) stopAnimation();
    },
    [onMouseLeave, stopAnimation]
  );

  return { handleMouseEnter, handleMouseLeave };
}
